mapper.select:
SELECT dt.id, dt.transfer_no, dt.from_hospital_id, dt.to_hospital_id, dt.status, dt.remark, dt.reject_reason, dt.created_by, dt.created_at, dt.updated_at, h1.name AS from_hospital_name, h2.name AS to_hospital_name, u.real_name AS created_by_name FROM drug_transfer dt LEFT JOIN hospital h1 ON dt.from_hospital_id = h1.id LEFT JOIN hospital h2 ON dt.to_hospital_id = h2.id LEFT JOIN sys_user u ON dt.created_by = u.id
AND dt.transfer_no LIKE CONCAT('%', #{transferNo}, '%') AND dt.from_hospital_id = #{fromHospitalId} AND dt.to_hospital_id = #{toHospitalId} AND dt.status = #{status}
ORDER BY dt.created_at DESC
